def reserve_existing_emails(apps,schema_editor):
    from collections import Counter
    import hashlib
    from django.conf import settings
    app,model=settings.AUTH_USER_MODEL.split('.')
    User=apps.get_model(app,model)
    Profile=apps.get_model('accounts','UserProfile')
    alias=schema_editor.connection.alias
    users=list(User.objects.using(alias).values_list('pk','email'))
    keys=[str(email or '').strip().casefold() for _,email in users]
    counts=Counter(key for key in keys if key)
    profiles=[]
    for (pk,_),key in zip(users,keys):
        reservation=hashlib.sha256(key.encode('utf-8')).hexdigest() if key and counts[key]==1 else None
        profiles.append(Profile(user_id=pk,email_key=reservation))
    Profile.objects.using(alias).bulk_create(profiles,batch_size=500)

